    assert set(reexport_names) == set(scheduler_module._SCHEDULER_LEASE_COMPAT_OWNER_REEXPORTS)
    assert set(reexport_names) == set(scheduler_module._SCHEDULER_LEASE_COMPAT_FACADE_REEXPORTS)
