def test_bounded_candidate_summary_retains_predecessor_pending_operator_signal() -> None:
    """#1152: the single-boolean triage must survive bounded summarization.

    §8.6 stalls append a blocked predecessor row every pass, so the passes that
    carry this evidence are exactly the ones most likely to overflow
    ``max_evidence_bytes`` and get summarized.  Dropping
    ``operator_action_required`` there would make the runbook's triage step
    ("read one boolean") unexecutable precisely where it is needed.
    """

    row = {
        "candidate_id": "gfs:2026-05-21T12:00:00Z:model_a:forecast_gfs_deterministic",
        "model_id": "model_a",
        "status": "blocked",
        "reason": "state_snapshot_index_prior_checkpoint_missing_after_history",
        "state_evidence": {
            "mode": "db_free_state_continuity",
            "required_prior_cycle_time": "2026-05-21T00:00:00Z",
            "self_heal_expected": False,
            "operator_action_required": True,
            "operator_action": "backfill_predecessor_state",
            "runbook": "docs/runbooks/scheduler-dbfree-typed-reasons.md",
            "self_heal_probe": {"ready": False, "reason": "state_snapshot_index_object_missing"},
            "state_history": {"detail": _bounded_incident_verbose_text("predecessor-pending-history")},
        },
    }

    summary = scheduler_evidence_payload_module._bounded_candidate_summary(row)

    assert summary["operator_action_required"] is True
    assert summary["reason"] == "state_snapshot_index_prior_checkpoint_missing_after_history"
    assert set(summary) <= _BOUNDED_CANDIDATE_SUMMARY_ALLOWED_KEYS
    # Idempotent: a second pass over the already-summarized row keeps it.
    assert scheduler_evidence_payload_module._bounded_candidate_summary(summary) == summary

    # The retention guard is `value is not None` (scheduler_evidence_payload.py:265),
    # NOT truthiness — so the self-healing leg (`operator_action_required: False`,
    # emitted whenever the predecessor's own probe reads ready) must survive too.
    # A truthiness guard would silently erase the "no operator needed" half of the
    # triage and leave operators unable to distinguish it from an absent field.
    self_healing_row = {
        **row,
        "candidate_id": "gfs:2026-05-21T12:00:00Z:model_b:forecast_gfs_deterministic",
        "model_id": "model_b",
        "state_evidence": {
            **row["state_evidence"],
            "self_heal_expected": True,
            "operator_action_required": False,
            "self_heal_probe": {"ready": True, "reason": None},
        },
    }
    # No `operator_action` / `runbook`: the gate only attaches those on the
    # not-self-healing leg (scheduler_generation_gate.py:760-762).
    del self_healing_row["state_evidence"]["operator_action"]
    del self_healing_row["state_evidence"]["runbook"]

    self_healing_summary = scheduler_evidence_payload_module._bounded_candidate_summary(
        self_healing_row
    )

    assert "operator_action_required" in self_healing_summary
    assert self_healing_summary["operator_action_required"] is False
    assert set(self_healing_summary) <= _BOUNDED_CANDIDATE_SUMMARY_ALLOWED_KEYS
    assert (
        scheduler_evidence_payload_module._bounded_candidate_summary(self_healing_summary)
        == self_healing_summary
    )


def test_bounded_evidence_summary_rows_are_idempotent_under_a_second_fallback() -> None:
    payload = _incident_scheduler_evidence_payload("scheduler_2026072612_summary_idempotent")

    bounded = scheduler_module._bounded_evidence_payload(
        payload,
        reason="evidence_size_limit_exceeded",
        max_evidence_bytes=8_000,
    )

    # `_fit_bounded_evidence_payload` returns at its first fit check for an already
    # fitting payload, so the summary tier has to be driven directly to be observed.
    once = json.loads(json.dumps(bounded))
    scheduler_evidence_payload_module._summarize_bounded_candidate_lists(once)
    twice = json.loads(json.dumps(once))
    scheduler_evidence_payload_module._summarize_bounded_candidate_lists(twice)

    assert once == bounded
    assert twice == once
    # Fields whose second pass reads back this helper's own output.
    assert once["candidates"] == [_expected_bounded_selected_candidate_summary()]
    assert once["blocked_candidates"] == [_expected_bounded_blocked_candidate_summary()]
    assert once["skipped_candidates"] == _expected_bounded_skipped_candidate_summaries()
    assert once["skipped_candidates"][-1] == {"summary_error": "unrecognized_candidate_shape"}
    assert once["restart_reconcile"] == _expected_bounded_restart_reconcile()
    assert once["limit"]["candidate_lists"] == "summarized"


def test_fit_summary_tier_summarizes_injected_unsummarized_bounded_payload() -> None:
    """The `_fit` summary tier is load-bearing on a bounded payload that skipped it."""

    payload = _incident_scheduler_evidence_payload("scheduler_2026072612_fit_summary_tier")
    bounded = scheduler_module._bounded_evidence_payload(
        payload,
        reason="evidence_size_limit_exceeded",
        max_evidence_bytes=8_000,
    )

    unsummarized = json.loads(json.dumps(bounded))
    for field_name in ("candidates", "blocked_candidates", "skipped_candidates", "restart_reconcile"):
        unsummarized[field_name] = json.loads(json.dumps(payload[field_name]))
    # No `candidate_lists` marker yet, so the tier's own marking is what must supply it.
    unsummarized["limit"] = {key: value for key, value in bounded["limit"].items() if key != "candidate_lists"}
    assert len(json.dumps(unsummarized, separators=(",", ":"), sort_keys=True).encode("utf-8")) > 8_000

    fitted = scheduler_evidence_module._fit_bounded_evidence_payload(
        unsummarized,
        max_evidence_bytes=8_000,
    )
    rendered = json.dumps(fitted, separators=(",", ":"), sort_keys=True)

    assert len(rendered.encode("utf-8")) <= 8_000
    assert fitted["candidates"] == [_expected_bounded_selected_candidate_summary()]
    assert fitted["blocked_candidates"] == [_expected_bounded_blocked_candidate_summary()]
    assert fitted["skipped_candidates"] == _expected_bounded_skipped_candidate_summaries()
    assert fitted["restart_reconcile"] == _expected_bounded_restart_reconcile()
    assert fitted["limit"]["candidate_lists"] == "summarized"
    assert _BOUNDED_INCIDENT_VERBOSE_MARKER not in rendered


def test_summarize_tier_never_downgrades_dropped_candidate_lists() -> None:
    """`dropped` means rows were cut, so a later summary pass must not relabel it `summarized`."""

    payload = _incident_scheduler_evidence_payload("scheduler_2026072612_dropped_not_downgraded")

    # 2_200 runs the drop loop past every candidate list (see the droppable-tier test at
    # the same budget), leaving the marker at `dropped` with all three lists emptied.
    dropped = scheduler_module._bounded_evidence_payload(
        payload,
        reason="evidence_size_limit_exceeded",
        max_evidence_bytes=2_200,
    )
    assert dropped["limit"]["candidate_lists"] == "dropped"
    for field_name in ("candidates", "blocked_candidates", "skipped_candidates"):
        assert dropped[field_name] == []

    # The list keys are still present, so a second summary pass does summarize them; only
    # the tier's `dropped` guard keeps that pass from rewriting the marker.
    resummarized = json.loads(json.dumps(dropped))
    scheduler_evidence_payload_module._summarize_bounded_candidate_lists(resummarized)

    assert resummarized["limit"]["candidate_lists"] == "dropped"
    for field_name in ("candidates", "blocked_candidates", "skipped_candidates"):
        assert resummarized[field_name] == []
    assert resummarized == dropped


