        (
            {"slurm_env": {"DATABASE_URL": "postgresql://nhms:supersecret@db.prod.example/nhms"}},
            "SLURM_PREFLIGHT_ENV_SECRET_REJECTED",
        ),
        (
            {"slurm_env": {"NHMS_PROFILE": "https://user:supersecret@example.com/profile"}},
            "SLURM_PREFLIGHT_ENV_SECRET_REJECTED",
        ),
