        registry=FakeRegistry([_model("model_a", "basin_a")]),
        adapters={
            "gfs": FakeAdapter(
                "gfs",
                [
                    (
                        "2026-05-21T00:00:00Z",
                        False,
                        {"reason": "source_cycle_unavailable", "retryable": True},
                    ),
                    ("2026-05-21T06:00:00Z", True),
                    ("2026-05-21T12:00:00Z", True),
                ],
            )
        },
