def _slurm_roots(root: Path) -> dict[str, Path]:
    roots = {
        "workspace_root": root / "workspace",
        "object_store_root": root / "object-store",
        "published_root": root / "published",
        "log_root": root / "logs",
        "runtime_root": root / "runtime",
        "temp_root": root / "tmp",
    }
    for path in roots.values():
        path.mkdir(parents=True, exist_ok=True)
    return roots


def _scheduler_env_roots(root: Path) -> dict[str, Path]:
    workspace_root = root / "workspace"
    roots = {
        "workspace_root": workspace_root,
        "object_store_root": root / "object-store",
        "published_root": root / "published",
        "runtime_root": root / "runtime",
        "temp_root": root / "tmp",
        "lock_root": workspace_root / "locks",
        "evidence_root": workspace_root / "evidence",
    }
    # Explicit mode, not the ambient umask (#1513). These roots become the DIRECT
    # parent of provider locks, and `provider_atomic`'s gate is fail-closed on any
    # 0o022 bit there; a bare `Path.mkdir` lands 0o775 under umask 0002 and
    # reddens this whole file on node-27. `Path.mkdir(mode=..., parents=True)`
    # would not do -- it applies the mode to the leaf only.
    for path in roots.values():
        make_directory_with_explicit_mode(path)
    return roots


def _set_scheduler_root_env(monkeypatch: Any, roots: Mapping[str, Path]) -> None:
    monkeypatch.setenv("WORKSPACE_ROOT", str(roots["workspace_root"]))
    monkeypatch.setenv("OBJECT_STORE_ROOT", str(roots["object_store_root"]))
    monkeypatch.setenv("NHMS_PUBLISHED_ARTIFACT_ROOT", str(roots["published_root"]))
    monkeypatch.setenv("NHMS_SCHEDULER_RUNTIME_ROOT", str(roots["runtime_root"]))
    monkeypatch.setenv("NHMS_SCHEDULER_TEMP_ROOT", str(roots["temp_root"]))
    monkeypatch.setenv("NHMS_SCHEDULER_LOCK_ROOT", str(roots["lock_root"]))
    monkeypatch.setenv("NHMS_SCHEDULER_EVIDENCE_ROOT", str(roots["evidence_root"]))
    monkeypatch.setenv(
        "NHMS_SCHEDULER_ALLOWED_ROOTS",
        os.pathsep.join(
            str(roots[key])
            for key in ("workspace_root", "object_store_root", "published_root", "runtime_root", "temp_root")
        ),
    )
    monkeypatch.setenv("NHMS_SCHEDULER_ALLOWED_CYCLE_HOURS_UTC", "0,6,12,18")
    monkeypatch.setenv("NHMS_SCHEDULER_SOURCES", "gfs")
    monkeypatch.setenv("NHMS_SCHEDULER_MODEL_IDS", "model_a")
    monkeypatch.setenv("NHMS_SCHEDULER_BASIN_IDS", "basin_a")


_DB_FREE_SELECTOR_ENV_KEYS = (
    "NHMS_SCHEDULER_STATE_BACKEND",
    "NHMS_SCHEDULER_LOCK_BACKEND",
    "NHMS_SCHEDULER_REGISTRY_BACKEND",
    "NHMS_SCHEDULER_CANONICAL_READINESS_BACKEND",
    "NHMS_SCHEDULER_JOURNAL_BACKEND",
    "NHMS_SCHEDULER_STATE_INDEX_BACKEND",
)
_DB_FREE_PATH_ENV_KEYS = (
    "NHMS_SCHEDULER_REGISTRY_MANIFEST",
    "NHMS_SCHEDULER_CANONICAL_READINESS_INDEX",
    "NHMS_SCHEDULER_JOURNAL_ROOT",
    "NHMS_SCHEDULER_STATE_INDEX",
)
_DB_FREE_FILE_PATH_ENV_KEYS = tuple(
    key for key in _DB_FREE_PATH_ENV_KEYS if key != "NHMS_SCHEDULER_JOURNAL_ROOT"
)
_DB_FREE_SELECTOR_RUNTIME_CONFIG_FIELDS = {
    "NHMS_SCHEDULER_STATE_BACKEND": "scheduler_state_backend",
    "NHMS_SCHEDULER_LOCK_BACKEND": "scheduler_lock_backend",
    "NHMS_SCHEDULER_REGISTRY_BACKEND": "scheduler_registry_backend",
    "NHMS_SCHEDULER_CANONICAL_READINESS_BACKEND": "scheduler_canonical_readiness_backend",
    "NHMS_SCHEDULER_JOURNAL_BACKEND": "scheduler_journal_backend",
    "NHMS_SCHEDULER_STATE_INDEX_BACKEND": "scheduler_state_index_backend",
}


def _gfs_default_forecast_hours() -> tuple[int, ...]:
    return tuple(range(0, 169, 3))


def _set_db_free_scheduler_env(monkeypatch: Any, root: Path) -> tuple[dict[str, Path], dict[str, Path]]:
    roots = _scheduler_env_roots(root)
    _set_scheduler_root_env(monkeypatch, roots)
    monkeypatch.setenv("NHMS_SERVICE_ROLE", "compute_control")
    monkeypatch.setenv("NHMS_SCHEDULER_REQUIRE_ROOTS", "true")
    monkeypatch.setenv("NHMS_SCHEDULER_DB_FREE_REQUIRED", "true")
    monkeypatch.setenv("NHMS_SCHEDULER_RECONCILE_SLURM_USER", "scheduler-user")
    monkeypatch.setenv("NHMS_SCHEDULER_RECONCILE_SLURM_ACCOUNT", "scheduler-account")
    raw_manifest_root = roots["object_store_root"]
    monkeypatch.setattr(
        source_cycle_raw_manifest_module,
        "NODE22_CANONICAL_NFS_RAW_AUTHORITY_ROOT",
        raw_manifest_root,
        raising=False,
    )
    monkeypatch.setenv("NHMS_OBJECT_STORE_COPYBACK_ROOT", str(raw_manifest_root))
    monkeypatch.setenv("NHMS_SCHEDULER_NFS_RAW_MANIFEST_ROOT", str(raw_manifest_root))
    monkeypatch.setenv("NHMS_SCHEDULER_NFS_RAW_MANIFEST_PREFIX", "s3://nhms")
    monkeypatch.delenv("DATABASE_URL", raising=False)
    for key in _DB_FREE_SELECTOR_ENV_KEYS:
        monkeypatch.setenv(key, "file")
    db_free_dir = roots["workspace_root"] / "db-free"
    object_index_dir = roots["object_store_root"] / "db-free"
    # `object_index_dir` is the measured trip point (#1513): it is the direct
    # parent of the canonical-readiness and state-index provider locks.
    make_directory_with_explicit_mode(db_free_dir)
    make_directory_with_explicit_mode(object_index_dir)
    paths = {
        "NHMS_SCHEDULER_REGISTRY_MANIFEST": db_free_dir / "registry-manifest.json",
        "NHMS_SCHEDULER_CANONICAL_READINESS_INDEX": object_index_dir / "canonical-readiness-index.json",
        "NHMS_SCHEDULER_JOURNAL_ROOT": roots["workspace_root"] / "journal",
        "NHMS_SCHEDULER_STATE_INDEX": object_index_dir / "state-index.json",
    }
    for key, path in paths.items():
        if key in {
            "NHMS_SCHEDULER_JOURNAL_ROOT",
            "NHMS_SCHEDULER_NFS_RAW_MANIFEST_ROOT",
        }:
            make_directory_with_explicit_mode(path)
        else:
            # Explicit 0o644, not the ambient umask (#1513): these stubs are
            # provider DESTINATIONS, and `atomic_replace_provider_bytes` refuses
            # to publish over an existing file whose mode is not exactly
            # `SHARED_PROVIDER_MODE`. A bare `write_text` lands 0o664 under
            # umask 0002.
            write_provider_destination(path)
        monkeypatch.setenv(key, str(path))
    return roots, paths


def test_db_free_runtime_preflight_requires_explicit_trusted_nfs_raw_manifest_root(
    monkeypatch: Any,
    tmp_path: Path,
) -> None:
    _set_db_free_scheduler_env(monkeypatch, tmp_path)
    monkeypatch.delenv("NHMS_SCHEDULER_NFS_RAW_MANIFEST_ROOT", raising=False)

    preflight = ProductionSchedulerConfig().db_free_runtime_preflight()

    assert preflight["status"] == "blocked"
    blocker = next(
        item
        for item in preflight["blockers"]
        if item["field"] == "NHMS_SCHEDULER_NFS_RAW_MANIFEST_ROOT"
    )
    assert blocker["code"] == "db_free_required_path_missing"
    assert "OBJECT_STORE_ROOT" not in json.dumps(preflight, sort_keys=True)


def test_db_free_runtime_preflight_rejects_allowlisted_noncanonical_raw_authority_without_leak(
    monkeypatch: Any,
    tmp_path: Path,
) -> None:
    roots, _paths = _set_db_free_scheduler_env(monkeypatch, tmp_path)
    canonical_root = Path(os.environ["NHMS_OBJECT_STORE_COPYBACK_ROOT"])
    staging_root = roots["object_store_root"] / "allowlisted-staging" / "object-store"
    staging_root.mkdir(parents=True)
    monkeypatch.setenv("NHMS_SCHEDULER_NFS_RAW_MANIFEST_ROOT", str(staging_root))

    preflight = ProductionSchedulerConfig().db_free_runtime_preflight()
    rendered = json.dumps(preflight, sort_keys=True)

    assert preflight["status"] == "blocked"
    assert any(
        item["code"] == "db_free_raw_authority_mismatch"
        and item["field"] == "NHMS_SCHEDULER_NFS_RAW_MANIFEST_ROOT"
        for item in preflight["blockers"]
    )
    assert str(staging_root) not in rendered
    assert str(canonical_root) not in rendered


def test_db_free_runtime_preflight_rejects_copyback_and_raw_authority_rebound_together_without_work(
    monkeypatch: Any,
    tmp_path: Path,
) -> None:
    roots, _paths = _set_db_free_scheduler_env(monkeypatch, tmp_path)
    canonical_root = Path(os.environ["NHMS_OBJECT_STORE_COPYBACK_ROOT"])
    staging_root = roots["object_store_root"] / "allowlisted-staging" / "object-store"
    staging_root.mkdir(parents=True)
    monkeypatch.setenv("OBJECT_STORE_ROOT", str(staging_root))
    monkeypatch.setenv("NHMS_OBJECT_STORE_COPYBACK_ROOT", str(staging_root))
    monkeypatch.setenv("NHMS_SCHEDULER_NFS_RAW_MANIFEST_ROOT", str(staging_root))
    monkeypatch.setenv("NHMS_SCHEDULER_REPAIR_MISSING_FORCING", "true")
    monkeypatch.setenv("NHMS_SCHEDULER_REPAIR_MISSING_FORCING_CYCLE_TIME", "2026-07-12T00:00:00Z")
    monkeypatch.setenv("NHMS_SCHEDULER_BACKFILL_ENABLED", "false")
    monkeypatch.setenv("NHMS_SCHEDULER_LOOKBACK_HOURS", "0")
    monkeypatch.setenv("NHMS_SCHEDULER_MAX_CYCLES_PER_SOURCE", "1")
    monkeypatch.setattr("services.orchestrator.scheduler.FileSchedulerLease.acquire", _unexpected_lock_acquire)

    config = ProductionSchedulerConfig(
        backfill_enabled=False,
        lookback_hours=0,
        max_cycles_per_source=1,
    )
    preflight = config.db_free_runtime_preflight()
    result = ProductionScheduler.from_env(config).run_once()
    rendered = json.dumps({"preflight": preflight, "evidence": result.evidence}, sort_keys=True)

    assert preflight["status"] == "blocked"
    assert {
        item["field"]
        for item in preflight["blockers"]
        if item["code"] == "db_free_raw_authority_topology_mismatch"
    } == {
        "NHMS_OBJECT_STORE_COPYBACK_ROOT",
        "NHMS_SCHEDULER_NFS_RAW_MANIFEST_ROOT",
    }
    assert preflight["checks"]["NHMS_OBJECT_STORE_COPYBACK_ROOT"]["topology_matches"] is False
    assert preflight["checks"]["NHMS_SCHEDULER_NFS_RAW_MANIFEST_ROOT"]["topology_matches"] is False
    assert preflight["checks"]["NHMS_SCHEDULER_NFS_RAW_MANIFEST_ROOT"]["authority_matches"] is True
    assert result.status == "preflight_blocked"
    assert result.evidence["counts"]["submitted_count"] == 0
    assert str(staging_root) not in rendered
    assert str(canonical_root) not in rendered


