        pytest.param(_ABSENT_INIT_STATE_HYDRO_RUN, {"ready": False}, "gap", id="absent_successor_unusable"),
        pytest.param(_ABSENT_INIT_STATE_HYDRO_RUN, None, "gap", id="absent_successor_no_verdict"),
