def test_db_free_strict_warm_start_reopens_completed_producer_missing_successor_checkpoint(
    monkeypatch: Any,
    tmp_path: Path,
) -> None:
    roots, paths = _set_db_free_scheduler_env(monkeypatch, tmp_path / "db-free-local-root")
    cycle_time = _dt("2026-05-20T12:00:00Z")
    required_from = _dt("2026-05-21T00:00:00Z")
    generated_at = _dt("2026-05-21T12:00:00Z")
    fixture = _write_db_free_file_provider_fixtures(
        monkeypatch,
        roots,
        paths,
        cycle_time=cycle_time,
        forecast_hours=_gfs_default_forecast_hours(),
        generated_at=generated_at,
    )
    _write_db_free_state_index_fixture(
        roots,
        paths,
        cycle_time=required_from,
        package_checksum=fixture["package_checksum"],
        generated_at=generated_at,
        entries=[],
    )
    model = {
        **fixture["model"],
        "resource_profile": {
            **dict(fixture["model"]["resource_profile"]),
            "package_checksum": fixture["package_checksum"],
        },
    }

    class CompletedProducerRepository(FakeCandidateStateRepository):
        def has_completed_pipeline(self, *, source_id: str, cycle_time: datetime, model_id: str) -> bool:
            del source_id, cycle_time, model_id
            return True

    run_id = "fcst_gfs_2026052012_model_a"
    repository = CompletedProducerRepository(
        {
            "hydro_status": "published",
            "hydro_run": {
                "run_id": run_id,
                "status": "published",
                "init_state_id": None,
                "output_uri": f"s3://nhms/runs/{run_id}/output/",
            },
        }
    )
    monkeypatch.setenv("NHMS_REQUIRE_FORECAST_WARM_START", "true")
    monkeypatch.setenv("NHMS_FORECAST_WARM_START_REQUIRED_FROM", _format_iso_z(required_from))
    scheduler = ProductionScheduler(
        ProductionSchedulerConfig(now=generated_at, allowed_cycle_hours_utc=(0, 12)),
        registry=FakeRegistry([model]),
        adapters={},
        active_repository=repository,
        orchestrator_factory=lambda _source_id: pytest.fail("candidate construction must not build orchestrator"),
    )

    discovery = CycleDiscovery(
        cycle_id="gfs_2026052012",
        source_id="gfs",
        cycle_time=cycle_time,
        cycle_hour=12,
        available=True,
        status="discovered",
    )
    status = scheduler._cycle_completion_status(
        discovery,
        [scheduler_module._coerce_registered_model(model)],
        horizon={},
    )
    candidates, blocked, skipped, duplicate_exclusions, slurm_sync = scheduler._build_candidates(
        models=[scheduler_module._coerce_registered_model(model)],
        cycles=[scheduler_module.SchedulerSourceCycle(discovery=discovery, horizon={})],
    )

    assert status == "gap"
    assert len(candidates) == 1
    assert blocked == []
    assert skipped == []
    assert duplicate_exclusions == []
    assert slurm_sync == []
    evidence = candidates[0].state_evidence
    # §8.4 (#1081): an empty state index for a candidate cycle before
    # ``required_from`` now admits ``cold_new_model`` — no prior state
    # history in ANY generation.  The completed-producer retry logic still
    # reopens the terminal decision so state_evidence carries the retry
    # marker.  Under the strict-warm-start §8 admit shape, the fixture with
    # ``init_state_id=None`` deterministically drives the
    # ``strict_warm_start_terminal_init_state_mismatch`` branch of the
    # retry ladder in ``scheduler_candidates.py`` (the successor-checkpoint
    # branch requires a matching init_state_id first).
    #
    # A4 round-1 fix: restore the pre-§8 deterministic single-value
    # assertion and the two structural sub-field asserts that survive the
    # branch change — ``restart_stage`` and ``strict_warm_start.*`` (the
    # branch-specific ``successor_state`` field of the pre-§8 fixture does
    # not appear on this branch; the matching-init_state_id / missing
    # successor-checkpoint branch is covered by
    # ``test_db_free_terminal_success_reopens_when_successor_checkpoint_missing``).
    assert evidence["registry_cutover_transition"]["decision"] == "cold_new_model"
    assert evidence["generation"].startswith("manifest-")
    assert evidence["reason"] == "strict_warm_start_terminal_init_state_mismatch"
    assert evidence["restart_stage"] == "forecast"
    # ``strict_warm_start`` carries the §8 admit shape — proving the §8
    # gating fired at ready=True and that the retry evidence composed the
    # terminal-mismatch marker on top of the cold-start admit rather than
    # silently swallowing either signal.
    assert evidence["strict_warm_start"]["ready"] is True
    assert evidence["strict_warm_start"]["mode"] == "db_free_cold_new_model"
    assert (
        evidence["strict_warm_start"]["registry_cutover_transition"]["decision"]
        == "cold_new_model"
    )


