    assert len(blockers) == 1
    assert blockers[0]["code"] == _ALLOWED_ROOTS_UNSAFE_CODE
    assert blockers[0]["field"] == "allowed_storage_roots"
    assert blockers[0]["path"] == str(not_a_dir_root)


