def _repair_authority_config(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    *,
    allowed_storage_roots: tuple[Path, ...],
) -> ProductionSchedulerConfig:
    """A database-backed repair-authority run, adapted from `_missing_forcing_repair_config`.

    `db_free_runtime_preflight` runs here even though `scheduler_db_free_required`
    is False, because `repair_missing_forcing` skips its not-required early exit
    — and it adjudicates real containment for the copyback and raw-manifest
    roots on that pass.
    """

    authority_root = tmp_path / "repair-raw-authority"
    authority_root.mkdir(parents=True, exist_ok=True)
    monkeypatch.setattr(
        source_cycle_raw_manifest_module,
        "NODE22_CANONICAL_NFS_RAW_AUTHORITY_ROOT",
        authority_root,
        raising=False,
    )
    return _config(
        tmp_path,
        now=_dt("2026-05-21T12:00:00Z"),
        dry_run=True,
        lookback_hours=0,
        cycle_lag_hours=6,
        max_cycles_per_source=1,
        backfill_enabled=False,
        repair_missing_forcing=True,
        repair_missing_forcing_cycle_time=_dt("2026-05-21T06:00:00Z"),
        slurm_array_concurrency_bound=32,
        object_store_copyback_root=authority_root,
        nfs_raw_manifest_root=authority_root,
        nfs_raw_manifest_prefix="s3://nhms",
        database_url="postgresql://nhms:secret@db.prod.example/nhms",
        allowed_storage_roots=allowed_storage_roots,
    )


def test_db_free_runtime_preflight_blocks_unsafe_allowed_root_on_repair_authority_run(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Database-backed repair lane: the phantom containment base is eliminated.

    The lexical tolerance is a property of the db-free lane, not of a
    database-backed run passing through it, so here the unresolvable root is
    dropped and this lane's own blocker family records why. The copyback and
    raw-manifest containment verdicts on the same pass are then decided against
    the surviving approved root only.
    """

    loop = tmp_path / "authority-loop"
    loop.symlink_to(loop)
    config = _repair_authority_config(tmp_path, monkeypatch, allowed_storage_roots=(loop, tmp_path))
    assert config.scheduler_db_free_required is False
    assert config.repair_missing_forcing is True

    roots, blockers = scheduler_config_module._db_free_allowed_roots_and_blockers(config)
    preflight = config.db_free_runtime_preflight()

    assert roots == (tmp_path,)
    assert loop not in roots
    assert blockers == [
        {
            "code": "db_free_allowed_root_unsafe",
            "field": "NHMS_SCHEDULER_ALLOWED_ROOTS",
            "reason": "unsafe_path",
            "message": (
                "DB-free scheduler runtime field NHMS_SCHEDULER_ALLOWED_ROOTS "
                "is not a safe all-file configuration."
            ),
            "path": "[local-path]",
        }
    ]
    assert preflight["status"] == "blocked"
    assert blockers[0] in preflight["blockers"]
    assert preflight["checks"]["NHMS_OBJECT_STORE_COPYBACK_ROOT"]["contained"] is True
    assert preflight["checks"]["NHMS_SCHEDULER_NFS_RAW_MANIFEST_ROOT"]["contained"] is True
    assert str(loop) not in json.dumps(preflight, sort_keys=True)


def test_db_free_runtime_preflight_drops_every_containment_base_when_only_root_is_unsafe(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """With the loop as the only configured root the lane keeps no base at all.

    Fail-closed: the copyback/raw-manifest roots are then reported outside the
    boundary instead of being vouched for by a root the kernel cannot walk.
    """

    loop = tmp_path / "authority-loop"
    loop.symlink_to(loop)
    config = _repair_authority_config(tmp_path, monkeypatch, allowed_storage_roots=(loop,))

    roots, blockers = scheduler_config_module._db_free_allowed_roots_and_blockers(config)
    preflight = config.db_free_runtime_preflight()

    assert roots == ()
    assert [blocker["code"] for blocker in blockers] == ["db_free_allowed_root_unsafe"]
    assert preflight["status"] == "blocked"
    codes = [blocker["code"] for blocker in preflight["blockers"]]
    assert codes[0] == "db_free_allowed_root_unsafe"
    assert "db_free_required_path_outside_boundary" in codes
    assert preflight["checks"]["NHMS_OBJECT_STORE_COPYBACK_ROOT"]["contained"] is False


# Site 3 (retry.py db-free selector lane): the dead rejection becomes reachable.


@pytest.mark.parametrize("shape", ["loop", "not_a_directory"])
def test_db_free_selector_allowed_roots_rejects_unresolvable_root(
    tmp_path: Path,
    shape: str,
) -> None:
    """`db_free_allowed_root_unresolvable` really fires now.

    It was dead on both interpreter arms: `except OSError` could not catch the
    errno-less RuntimeError that strict-ish `Path.resolve()` raised on <=3.12,
    and on 3.13+ non-strict resolution stopped raising at all, so an
    unresolvable root was silently admitted as a containment base.
    """

    if shape == "loop":
        root = tmp_path / "selector-loop"
        root.symlink_to(root)
        expected_errno = errno.ELOOP
    else:
        regular_file = tmp_path / "plain.txt"
        regular_file.write_text("not a directory", encoding="utf-8")
        root = regular_file / "root"
        expected_errno = errno.ENOTDIR
    approved = tmp_path / "approved"
    approved.mkdir()
    assert _allowed_root_errno(root) == expected_errno

    roots, rejected = retry_module._db_free_selector_allowed_roots(
        "runtime_manifest",
        os.pathsep.join((str(root), str(approved))),
    )

    assert roots == (approved,)
    assert rejected == [
        {
            "field": "scheduler_allowed_roots",
            "source": "runtime_manifest",
            "reason": "db_free_allowed_root_unresolvable",
            "value": str(root),
        }
    ]


def test_db_free_selector_allowed_roots_admits_missing_root(tmp_path: Path) -> None:
    """ENOENT is not "unresolvable": a merely missing root stays admitted.

    `<missing>/../<realdir>` discriminates canonicalisation from lexical
    pass-through, which a bare missing leaf cannot: it is already canonical, so
    both candidate products coincide and the assertion goes blind.
    """

    realdir = tmp_path / "realdir"
    realdir.mkdir()
    lexical_root = tmp_path / "gone" / ".." / "realdir"
    canonical_root = Path(os.path.realpath(lexical_root))
    # Guard the discriminator itself: if these ever coincide the anchor is blind.
    assert canonical_root != lexical_root
    assert canonical_root == Path(os.path.realpath(realdir))
    assert _allowed_root_errno(lexical_root) == errno.ENOENT

    roots, rejected = retry_module._db_free_selector_allowed_roots("runtime_manifest", str(lexical_root))

    assert roots == (canonical_root,)
    assert roots != (lexical_root,)
    assert rejected == []


def test_db_free_selector_path_rejection_when_every_allowed_root_is_unresolvable(
    tmp_path: Path,
) -> None:
    """Cascade: with no surviving root the selector path lane fails closed."""

    loop = tmp_path / "selector-loop"
    loop.symlink_to(loop)
    inside = tmp_path / "inside"
    inside.mkdir()

    roots, rejected = retry_module._db_free_selector_allowed_roots("runtime_manifest", str(loop))
    rejection = retry_module._db_free_selector_path_rejection(
        "scheduler_registry_manifest",
        "runtime_manifest",
        str(inside / "registry.json"),
        allowed_roots=roots,
    )

    assert roots == ()
    assert [item["reason"] for item in rejected] == ["db_free_allowed_root_unresolvable"]
    assert rejection is not None
    assert rejection["reason"] == "db_free_allowed_roots_missing"


# ---------------------------------------------------------------------------
# #1427 (selector ROOT level) + #1400 (selector PATH level): the ENOENT
# admission at both levels is loop-filtered, not errno-scoped alone.  Strict
# resolution stops at the first missing component, so a "<missing>/../<loop>"
# phantom fails with ENOENT while its non-strict fallback still lands on the
# loop -- the two levels would otherwise hand one physical target two opposite
# verdicts, and the path level is judged against the root level's product.
# Unless a case is explicitly about out-of-root values, every geometry below
# keeps the loop lexically UNDER a cleanly resolving root, so that a containment
# rejection can never stand in for a resolution one.
# ---------------------------------------------------------------------------


def test_db_free_selector_allowed_roots_rejects_phantom_loop_root(tmp_path: Path) -> None:
    """#1427 AC-1: `<missing>/../<loop>` draws the bare loop's verdict.

    The direct form is already rejected by the ELOOP arm above; this form is the
    one the errno split alone admitted, and it is the ONLY carrier of the defect
    (a phantom root that resolves cleanly is legitimately admitted).
    """

    canonical_tmp = Path(os.path.realpath(tmp_path))
    loop = _symlink_loop_dir(canonical_tmp, "phantom-ring")
    phantom_root = canonical_tmp / "gone" / ".." / loop.name
    # Guard the geometry: strict resolution really does answer ENOENT here (not
    # ELOOP), and the non-strict fallback really does land on the loop.
    assert _allowed_root_errno(phantom_root) == errno.ENOENT
    assert Path(os.path.realpath(phantom_root)) == loop

    roots, rejected = retry_module._db_free_selector_allowed_roots("runtime_manifest", str(phantom_root))

    assert roots == ()
    assert rejected == [
        {
            "field": "scheduler_allowed_roots",
            "source": "runtime_manifest",
            "reason": "db_free_allowed_root_unresolvable",
            "value": str(phantom_root),
        }
    ]


def test_db_free_selector_allowed_roots_admits_never_created_root(tmp_path: Path) -> None:
    """The second-ENOENT arm keeps its admitted semantics.

    ``test_db_free_selector_allowed_roots_admits_missing_root`` above cannot
    carry this: its `<missing>/../<realdir>` form re-resolves CLEANLY, so the
    re-check's errno predicate is never evaluated there and a mutation that
    makes the predicate vacuous stays invisible.  A root that simply has not
    been created yet (an unmounted share) is the shape that evaluates it.
    """

    canonical_tmp = Path(os.path.realpath(tmp_path))
    not_yet = canonical_tmp / "not-yet" / "roots"
    # Both resolutions answer ENOENT: the strict one and the strict re-check of
    # the non-strict fallback.
    assert _allowed_root_errno(not_yet) == errno.ENOENT
    assert _allowed_root_errno(Path(os.path.realpath(not_yet))) == errno.ENOENT

    roots, rejected = retry_module._db_free_selector_allowed_roots("runtime_manifest", str(not_yet))

    assert roots == (not_yet,)
    assert rejected == []


def test_db_free_selector_path_rejection_admits_never_created_path(tmp_path: Path) -> None:
    """Submission-time adjudication still performs no existence check.

    The equality below is the byte-compatibility anchor: the primitive this lane
    now normalizes through reproduces the product of the removed
    ``path.resolve(strict=False)`` verbatim, so the admitted value did not drift.
    """

    canonical_tmp = Path(os.path.realpath(tmp_path))
    root = canonical_tmp / "clean-root"
    root.mkdir()
    never_created = root / "never-created" / "state.json"
    assert _allowed_root_errno(never_created) == errno.ENOENT
    assert Path(os.path.realpath(never_created)) == never_created.resolve(strict=False)

    rejection = retry_module._db_free_selector_path_rejection(
        "scheduler_state_index",
        "runtime_manifest",
        str(never_created),
        allowed_roots=(root,),
    )

    assert rejection is None


@pytest.mark.parametrize("shape", ["the_loop_itself", "under_the_loop"])
def test_db_free_selector_path_rejection_rejects_symlink_loop_path(tmp_path: Path, shape: str) -> None:
    """#1400 AC-1: the dead `db_free_selector_path_unresolvable` really fires.

    It was dead on both interpreter arms -- `except OSError` could not catch the
    errno-less RuntimeError strict ``Path.resolve()`` raised on <=3.12, and the
    non-strict form stopped raising at all on 3.13+, so the loop was admitted by
    a purely lexical containment comparison.
    """

    canonical_tmp = Path(os.path.realpath(tmp_path))
    root = canonical_tmp / "clean-root"
    root.mkdir()
    loop = _symlink_loop_dir(root, "selector-ring")
    value = loop if shape == "the_loop_itself" else loop / "state.json"
    # The loop is lexically inside the configured root, so containment cannot be
    # the reason for the rejection.
    assert value.is_relative_to(root)

    rejection = retry_module._db_free_selector_path_rejection(
        "scheduler_state_index",
        "runtime_manifest",
        str(value),
        allowed_roots=(root,),
    )

    assert rejection == {
        "field": "scheduler_state_index",
        "source": "runtime_manifest",
        "reason": "db_free_selector_path_unresolvable",
        "value": str(value),
    }


def test_db_free_selector_path_rejection_rejects_phantom_loop_path(tmp_path: Path) -> None:
    """The path level carries the same loop-filtered admission as the root level.

    Without the re-check this value takes the ENOENT arm and is admitted, which
    would reproduce one level down the fail-open #1427 removes one level up.
    """

    canonical_tmp = Path(os.path.realpath(tmp_path))
    root = canonical_tmp / "clean-root"
    root.mkdir()
    loop = _symlink_loop_dir(root, "selector-ring")
    phantom = root / "never-created" / ".." / loop.name
    assert _allowed_root_errno(phantom) == errno.ENOENT
    assert Path(os.path.realpath(phantom)) == loop

    rejection = retry_module._db_free_selector_path_rejection(
        "scheduler_state_index",
        "runtime_manifest",
        str(phantom),
        allowed_roots=(root,),
    )

    # The COMPLETE record, matching the sibling loop case above: the reason
    # alone would not catch a rejection routed with the wrong field, source or
    # echoed value.
    assert rejection == {
        "field": "scheduler_state_index",
        "source": "runtime_manifest",
        "reason": "db_free_selector_path_unresolvable",
        "value": str(phantom),
    }


def test_db_free_selector_path_rejection_rejects_every_non_enoent_errno(tmp_path: Path) -> None:
    """The rejection is errno-scoped, not loop-scoped.

    ENOTDIR is the non-loop errno provokable without a real NFS server or a
    permission trick; ESTALE and EACCES land on the same arm by construction.
    """

    canonical_tmp = Path(os.path.realpath(tmp_path))
    root = canonical_tmp / "clean-root"
    root.mkdir()
    plainfile = root / "plainfile"
    plainfile.write_text("not a directory", encoding="utf-8")
    value = plainfile / "state.json"
    assert _allowed_root_errno(value) == errno.ENOTDIR

    rejection = retry_module._db_free_selector_path_rejection(
        "scheduler_state_index",
        "runtime_manifest",
        str(value),
        allowed_roots=(root,),
    )

    # The COMPLETE record, matching the sibling loop case above.
    assert rejection == {
        "field": "scheduler_state_index",
        "source": "runtime_manifest",
        "reason": "db_free_selector_path_unresolvable",
        "value": str(value),
    }


def test_db_free_lanes_report_the_resolution_reason_for_out_of_root_loops(tmp_path: Path) -> None:
    """Resolution now precedes containment, so the reason changes for one subclass.

    A value that is BOTH a loop and outside the bases now reports the resolution
    reason rather than the containment one -- an unresolvable value has no
    trustworthy location to compare against.  Both were already rejections, so
    the verdict is unchanged; a cleanly resolving out-of-root value (the control
    below) keeps the containment reason untouched.
    """

    canonical_tmp = Path(os.path.realpath(tmp_path))
    root = canonical_tmp / "clean-root"
    root.mkdir()
    outside = canonical_tmp / "outside"
    outside.mkdir()
    outside_loop = _symlink_loop_dir(outside, "outside-ring")
    outside_clean = outside / "plain"
    outside_clean.mkdir()

    def _selector_reason(value: Path) -> str | None:
        rejection = retry_module._db_free_selector_path_rejection(
            "scheduler_state_index",
            "runtime_manifest",
            str(value),
            allowed_roots=(root,),
        )
        return None if rejection is None else rejection["reason"]

    assert _selector_reason(outside_loop) == "db_free_selector_path_unresolvable"
    assert _selector_reason(outside_clean) == "db_free_selector_path_outside_allowed_roots"
    assert _db_free_required_path_verdict(outside_loop, (root,)) == (
        "db_free_required_path_unsafe",
        "unsafe_path",
    )
    assert _db_free_required_path_verdict(outside_clean, (root,)) == (
        "db_free_required_path_outside_boundary",
        "outside_boundary",
    )


@pytest.mark.skipif(os.geteuid() == 0, reason="root bypasses directory permissions, so EACCES cannot be provoked")
def test_db_free_required_path_permission_fault_is_attributed_as_not_writable(tmp_path: Path) -> None:
    """The reason mapper's EACCES/EPERM arm, which no other case reaches.

    ``db_free_required_path_unsafe`` now carries the shared errno
    classification, and the loop cases above only ever witness its
    ``unsafe_path`` value -- with them alone the whole mapper is
    indistinguishable from a constant. EACCES is the one non-loop errno
    provokable without a real NFS server (an unreadable parent directory);
    EPERM and the ``unavailable`` catch-all land on the same mapping by
    construction, the latter witnessed by the NUL case below.
    """

    canonical_tmp = Path(os.path.realpath(tmp_path))
    root = canonical_tmp / "clean-root"
    root.mkdir()
    blocked_parent = root / "blocked-parent"
    blocked_parent.mkdir()
    value = blocked_parent / "journal"
    blocked_parent.chmod(0o000)
    try:
        # Independent oracle for the geometry: the kernel really does refuse
        # this canonicalization with EACCES (so neither the ENOENT fallback nor
        # the ELOOP/ENOTDIR mapping is what answers), and the earlier component
        # gate stays silent, so the resolution step is what adjudicates.
        assert scheduler_config_module._db_free_local_path_component_reason(value) is None
        assert _allowed_root_errno(value) == errno.EACCES

        assert _db_free_required_path_verdict(value, (root,)) == (
            "db_free_required_path_unsafe",
            "not_writable",
        )
    finally:
        # Restore before pytest's tmp_path cleanup walks the tree.
        blocked_parent.chmod(0o700)


def test_db_free_normalization_folds_embedded_nul_into_existing_rejections(tmp_path: Path) -> None:
    """An unrepresentable path string is rejected, not raised, at all three sites.

    Every resolution primitive raises ``ValueError`` (not ``OSError``) for an
    embedded NUL, so before this change it escaped each adjudicator: measured
    ``ValueError: lstat: embedded null character in path``.
    """

    canonical_tmp = Path(os.path.realpath(tmp_path))
    root = canonical_tmp / "clean-root"
    root.mkdir()
    nul_value = f"{root}/state\x00.json"

    roots, root_rejections = retry_module._db_free_selector_allowed_roots("runtime_manifest", nul_value)
    path_rejection = retry_module._db_free_selector_path_rejection(
        "scheduler_state_index",
        "runtime_manifest",
        nul_value,
        allowed_roots=(root,),
    )
    _check, required_path_blocker = scheduler_config_module._db_free_path_check(
        "NHMS_SCHEDULER_STATE_INDEX",
        nul_value,
        kind="file",
        allowed_roots=(root,),
    )

    assert roots == ()
    assert [item["reason"] for item in root_rejections] == ["db_free_allowed_root_unresolvable"]
    assert path_rejection is not None
    assert path_rejection["reason"] == "db_free_selector_path_unresolvable"
    assert required_path_blocker is not None
    assert required_path_blocker["code"] == "db_free_required_path_unsafe"
    # The reason too, not just the code: a ValueError carries no errno, so it
    # takes the mapper's ``unavailable`` catch-all rather than the ``unsafe_path``
    # the loop cases produce. Without this pin that arm of the mapper is
    # unwitnessed.
    assert required_path_blocker["reason"] == "unavailable"
    assert required_path_blocker["error_type"] == "ValueError"


def test_db_free_slurm_preflight_masks_env_and_grib_paths(
    monkeypatch: Any,
    tmp_path: Path,
) -> None:
    roots, _paths = _set_db_free_scheduler_env(monkeypatch, tmp_path / "approved")
    log_root = roots["workspace_root"] / "logs"
    log_root.mkdir()
    grib_root = tmp_path / "nfs" / "unsafe-secret-token" / "grib"
    config = ProductionSchedulerConfig(
        slurm_execution_enabled=True,
        log_root=log_root,
        slurm_env={
            "NHMS_PROFILE": str(tmp_path / "profiles" / "unsafe-secret-token"),
            "NHMS_DB_HINT": "postgresql://db.internal.example:55433/nhms",
            "NHMS_GRIB_ENV_ROOT": str(grib_root),
        },
    )

    preflight = scheduler_module._slurm_preflight(config)
    rendered = json.dumps(preflight, sort_keys=True)

    assert preflight["status"] == "blocked"
    assert preflight["checks"]["environment"]["sanitized"]["NHMS_PROFILE"] == "[redacted]"
    assert preflight["checks"]["environment"]["sanitized"]["NHMS_DB_HINT"] == "[db-like]"
    assert preflight["checks"]["environment"]["sanitized"]["NHMS_GRIB_ENV_ROOT"] == "[redacted]"
    assert preflight["checks"]["grib_env"]["root"] == "[redacted]"
    assert preflight["checks"]["grib_env"]["bin_present"] is False
    assert preflight["checks"]["grib_env"]["lib_present"] is False
    grib_blocker = next(
        blocker for blocker in preflight["blockers"] if blocker["code"] == "GRIB_ENV_ROOT_INVALID"
    )
    assert grib_blocker["root"] == "[redacted]"
    assert grib_blocker["bin_present"] is False
    assert grib_blocker["lib_present"] is False
    assert "unsafe-secret-token" not in rendered
    assert "postgresql" not in rendered.lower()
    assert "db.internal.example" not in rendered
    assert "55433" not in rendered
    assert str(grib_root) not in rendered


# --- Issue #257 / M23-6: scheduler SHUD executable pre-submit preflight -------


class _AssertNoSubmitOrchestrator:
    """Orchestrator that fails the test if it is ever invoked.

    Does not allocate a LocalObjectStore, so it is safe to construct on any
    platform (unlike FakeProductionOrchestrator).
    """

    def __init__(self) -> None:
        self.calls: list[dict[str, Any]] = []

    def orchestrate_cycle(self, source: str, cycle_time: datetime, basins: list[dict[str, Any]]) -> Any:
        self.calls.append({"source": source, "cycle_time": cycle_time, "basins": basins})
        raise AssertionError("orchestrator must not run when SHUD preflight blocks submission")


def _slurm_shud_scheduler(tmp_path: Path, *, shud_executable: str) -> tuple[Any, Any]:
    roots = _slurm_roots(tmp_path)
    orchestrator = _AssertNoSubmitOrchestrator()
    config = _config(
        roots["workspace_root"],
        now=_dt("2026-05-21T12:00:00Z"),
        dry_run=False,
        slurm_execution_enabled=True,
        database_url="postgresql://nhms:secret@db.prod.example/nhms",
        object_store_root=roots["object_store_root"],
        log_root=roots["log_root"],
        runtime_root=roots["runtime_root"],
        allowed_storage_roots=(tmp_path,),
        slurm_env={"SHUD_EXECUTABLE": shud_executable},
    )
    scheduler = ProductionScheduler(
        config,
        registry=FakeRegistry([_model("model_a", "basin_a")]),
        adapters={"gfs": FakeAdapter("gfs", [("2026-05-21T06:00:00Z", True)])},
        orchestrator_factory=lambda _source_id: orchestrator,
    )
    return scheduler, orchestrator


@pytest.mark.parametrize(
    ("shud_executable", "expected_code"),
    [
        ("/bin/true", "SHUD_EXECUTABLE_STUB_REJECTED"),
        ("/bin/false", "SHUD_EXECUTABLE_STUB_REJECTED"),
        ("", "SHUD_EXECUTABLE_NOT_CONFIGURED"),
        ("/nonexistent/shud_omp", "SHUD_EXECUTABLE_MISSING"),
    ],
)
def test_scheduler_slurm_preflight_blocks_stub_or_missing_shud_before_submit(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    shud_executable: str,
    expected_code: str,
) -> None:
    # The empty case must also clear the ambient SHUD_EXECUTABLE env so the
    # scheduler cannot fall back to a valid one set by the autouse fixture.
    if shud_executable == "":
        monkeypatch.delenv("SHUD_EXECUTABLE", raising=False)
    scheduler, orchestrator = _slurm_shud_scheduler(tmp_path, shud_executable=shud_executable)

    result = scheduler.run_once()

    assert result.status == "preflight_blocked"
    assert result.evidence["execution_boundary"] == "slurm_preflight_blocked"
    assert result.evidence["counts"]["submitted_count"] == 0
    # No Slurm submission, no active pipeline job, no hydro success state.
    assert result.evidence["no_mutation_proof"]["slurm_submit_called"] is False
    assert orchestrator.calls == []
    blocker_codes = {b["code"] for b in result.evidence["slurm_preflight"]["blockers"]}
    assert expected_code in blocker_codes
    model_run = result.evidence["model_run_evidence"][0]
    assert model_run["status"] == "preflight_blocked"
    assert model_run["submitted"] is False
    assert "secret" not in json.dumps(result.evidence)


def test_scheduler_slurm_preflight_does_not_leak_library_secrets(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    binary = tmp_path / "shud_omp"
    binary.write_text('#!/bin/sh\necho "SHUD"\n', encoding="utf-8")
    binary.chmod(0o755)

    import packages.common.shud_preflight as preflight

    monkeypatch.setattr(preflight, "_missing_shared_libraries", lambda _resolved: ["libqhh-token.so.2"])
    monkeypatch.setattr(preflight, "_version_identity_signal", lambda _resolved: "present")

    scheduler, orchestrator = _slurm_shud_scheduler(tmp_path, shud_executable=str(binary))

    result = scheduler.run_once()

    assert result.status == "preflight_blocked"
    assert orchestrator.calls == []
    blockers = result.evidence["slurm_preflight"]["blockers"]
    library_blockers = [b for b in blockers if b["code"] == "SHUD_EXECUTABLE_LIBRARY_MISSING"]
    assert library_blockers
    assert library_blockers[0]["library"] == "libqhh-token.so.2"
    assert "password" not in json.dumps(result.evidence)


# --- M23-7 (#258): node-22 Slurm gateway preflight ---------------------------


def _gateway_config(tmp_path: Path, **kwargs: Any) -> ProductionSchedulerConfig:
    defaults = {
        "slurm_execution_enabled": True,
        "database_url": "postgresql://nhms:secret@db.prod.example/nhms",
    }
    defaults.update(kwargs)
    return _config(tmp_path, **defaults)


def _healthy_gateway_probe(_config: ProductionSchedulerConfig) -> dict[str, Any]:
    return {
        "mode": "real",
        "backend": "slurm",
        "version": "24.05",
        "healthy": True,
        "submit_capable": True,
        "accounting_available": True,
    }


def test_slurm_gateway_check_healthy_records_mode_without_credentials(tmp_path: Path) -> None:
    config = _gateway_config(tmp_path, slurm_gateway_url="https://user:pass@gw-node22.internal:8000")

    checks, blockers = scheduler_module._slurm_gateway_check(config, probe=_healthy_gateway_probe)

    assert blockers == []
    assert checks["mode"] == "real"
    assert checks["endpoint"]["host"] == "gw-node22.internal"
    # Credentials in the URL must never reach evidence.
    serialized = json.dumps(checks)
    assert "pass" not in serialized
    assert "user" not in serialized


def test_slurm_gateway_check_unavailable_blocks(tmp_path: Path) -> None:
    config = _gateway_config(tmp_path, slurm_gateway_url="http://gw-node22.internal:8000")

    def unhealthy(_config: ProductionSchedulerConfig) -> dict[str, Any]:
        return {"mode": "real", "healthy": False, "reason": "sinfo --version failed"}

    checks, blockers = scheduler_module._slurm_gateway_check(config, probe=unhealthy)

    codes = {b["code"] for b in blockers}
    assert "SLURM_GATEWAY_UNAVAILABLE" in codes
    assert checks["healthy"] is False


def test_slurm_gateway_check_self_reference_blocks_with_real_backend(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(scheduler_module, "_slurm_gateway_backend", lambda: "real")
    config = _gateway_config(tmp_path, slurm_gateway_url="http://localhost:8000", service_port=8000)

    checks, blockers = scheduler_module._slurm_gateway_check(config, probe=_healthy_gateway_probe)

    codes = {b["code"] for b in blockers}
    assert "SLURM_GATEWAY_SELF_REFERENCE" in codes
    # Self-reference is decisive: the probe must not also be consulted.
    assert checks["self_reference"] is True


