    assert block["open"] == []
    assert outside.read_text(encoding="utf-8") == outside_payload
    assert tracker.is_symlink() is False
    assert json.loads(tracker.read_text(encoding="utf-8"))["entries"][0]["consecutive_passes"] == 1


